<template>
  <el-dialog
    title="广告设置"
    :visible.sync="dialogFormVisible"
    v-if="dialogFormVisible"
  >
    <el-form ref="adSettingForm" :model="form" :inline="true" :rules="rules">
      <el-form-item label="广告类型" :label-width="formLabelWidth">
        <el-select v-model="form.type" @change="uploaderRender">
          <el-option label="图片广告" value="image"></el-option>
          <el-option label="文字广告" value="text"></el-option>
        </el-select>
      </el-form-item>
      <el-form-item label="状态" :label-width="formLabelWidth">
        <el-switch
          v-model="form.status"
          active-color="#13ce66"
          inactive-color="#ff4949"
          :active-value="1"
          :inactive-value="0"
        >
        </el-switch>
      </el-form-item>
      <el-form-item
        label="PC端广告图"
        :label-width="formLabelWidth"
        v-if="form.type === 'image'"
      >
        <vr-upload
          ref="adPcImgUploader"
          key="adPcImgUploader"
          uploadClass="upload-img-container"
          tip="尺寸：1456 X 180;jpg、png格式"
          listType
          :showDelAction="true"
          :cropImg="false"
          :cropFixed="false"
          cropDialogTop="2vh"
          :cropDialogModal="false"
          :autoCropWidth="1456"
          :autoCropHeight="180"
          :autoUpload="true"
          @onSuccess="onAdPcUploadSuccess"
          @onClearFile="onAdPcClearLogoFile"
        />
      </el-form-item>
      <el-form-item
        label="移动端广告图"
        :label-width="formLabelWidth"
        v-if="form.type === 'image'"
      >
        <vr-upload
          ref="adMobileImgUploader"
          key="adMobileImgUploader"
          uploadClass="upload-img-container"
          tip="尺寸：600 X 100;jpg、png格式"
          listType
          :showDelAction="true"
          :cropImg="true"
          :cropFixed="false"
          cropDialogTop="2vh"
          cropDialogWidth="1300px"
          :cropDialogModal="false"
          :autoCropWidth="600"
          :autoCropHeight="100"
          :autoUpload="false"
          @onSuccess="onAdMobileUploadSuccess"
          @onClearFile="onAdMobileClearLogoFile"
        />
      </el-form-item>
      <el-form-item
        label="广告内容"
        :label-width="formLabelWidth"
        v-if="form.type === 'text'"
      >
        <el-input
          type="textarea"
          placeholder="请输入广告内容"
          v-model="form.content"
          maxlength="200"
          rows="8"
          show-word-limit
        />
      </el-form-item>
      <el-form-item
        label="地面遮罩图"
        :label-width="formLabelWidth"
      >
        <vr-upload
          ref="bottomMaskUploader"
          key="bottomMaskUploader"
          uploadClass="upload-img-container"
          tip="尺寸：500 X 500"
          listType
          :showDelAction="true"
          :cropImg="false"
          :cropFixed="true"
          cropDialogTop="2vh"
          :cropDialogModal="false"
          :autoCropWidth="500"
          :autoCropHeight="500"
          :autoUpload="true"
          @onSuccess="onBottomMaskUploadSuccess"
          @onClearFile="onBottomMaskClearLogoFile"
        />
      </el-form-item>
      <el-form-item label="网址" :label-width="formLabelWidth">
        <el-input
          type="input"
          placeholder="请输入(http|https)://"
          v-model="form.link"
          maxlength="200"
          show-word-limit
        />
      </el-form-item>
      <el-form-item label="打开方式" :label-width="formLabelWidth">
        <el-select v-model="form.link_target">
          <el-option
            v-for="item in linkTargetOptions"
            :key="item.value"
            :label="item.label"
            :value="item.value"
          >
          </el-option>
        </el-select>
      </el-form-item>
    </el-form>
    <div slot="footer" class="dialog-footer">
      <el-button @click="onCancel">取 消</el-button>
      <el-button type="primary" @click="onSave">确 定</el-button>
    </div>
  </el-dialog>
</template>

<script>
// eslint-disable-next-line no-unused-vars
import { getProductConfig, setProductConfig } from '@/api/vr'
const defaultForm = {
  status: 1,
  type: 'image', // image = 图片广告, text =文字广告(文字+地面遮罩)
  pc_ad_img: '',
  pc_ad_img_full: '',
  mobile_ad_img: '',
  mobile_ad_img_full: '',
  content: '',
  link: '',
  link_target: '_blank',
  bottom_mask_img: '',
  bottom_mask_img_full: '',
}
export default {
  name: 'adConfig',
  components: {
    VrUpload: () => import('@/components/VrUpload.vue'),
  },
  data() {
    return {
      dialogFormVisible: false,
      form: Object.assign({}, defaultForm),
      rules: {
        link: [{ type: 'url', message: '请输入合法的网址', trigger: 'blur' }],
      },
      formLabelWidth: '120px',
      linkTargetOptions: [
        {
          value: '_blank',
          label: '新窗口打开',
        },
        {
          value: '_self',
          label: '当前窗口打开',
        },
        {
          value: '_top',
          label: '弹出窗口打开',
        },
        {
          value: '_parent',
          label: '父窗口打开',
        },
      ],
    }
  },
  props: {
    productId: null,
  },
  methods: {
    async init() {
      this.dialogFormVisible = true
      await this.getConfig()
    },
    async getConfig() {
      const config = await getProductConfig(this.productId, 'product_ad')
      if (config) {
        this.form = config.val
      }
      this.uploaderRender()
    },
    uploaderRender() {
      this.$nextTick(() => {
        if (this.form.type === 'image') {
          if (this.$refs.adPcImgUploader) {
            this.$refs.adPcImgUploader.initFileList([
              {
                name: 'PC端广告',
                path: this.form.pc_ad_img,
                url: this.form.pc_ad_img_full,
              },
            ])
          }

          if (this.$refs.adMobileImgUploader) {
            this.$refs.adMobileImgUploader.initFileList([
              {
                name: '移动端广告',
                path: this.form.mobile_ad_img,
                url: this.form.mobile_ad_img_full,
              },
            ])
          }
        }

        if (this.$refs.bottomMaskUploader) {
            this.$refs.bottomMaskUploader.initFileList([
              {
                name: '地面遮罩图',
                path: this.form.bottom_mask_img,
                url: this.form.bottom_mask_img_full,
              },
            ])
          }
      })
    },
    onAdPcUploadSuccess(data) {
      this.form.pc_ad_img = data.path
    },
    onAdPcClearLogoFile() {
      this.form.pc_ad_img = ''
    },
    onAdMobileUploadSuccess(data) {
      this.form.mobile_ad_img = data.path
    },
    onAdMobileClearLogoFile() {
      this.form.mobile_ad_img = ''
    },
    onBottomMaskUploadSuccess(data) {
      this.form.bottom_mask_img = data.path
    },
    onBottomMaskClearLogoFile() {
      this.form.bottom_mask_img = ''
    },
    onCancel() {
      this.form = Object.assign({}, defaultForm)
      this.$refs.adSettingForm.resetFields()
      this.dialogFormVisible = false
    },
    onSave() {
      this.$refs.adSettingForm.validate((valid) => {
        if (valid) {
          setProductConfig(this.productId, 'product_ad', {
            status: this.form.status,
            type: this.form.type,
            pc_ad_img: this.form.pc_ad_img,
            mobile_ad_img: this.form.mobile_ad_img,
            content: this.form.content,
            link: this.form.link,
            link_target: this.form.link_target,
            bottom_mask_img: this.form.bottom_mask_img,
          }).then((data, message) => {
            console.log('data, message:', data, message)
            this.$message.success('设置成功')
            this.onCancel()
          })
        } else {
          return false
        }
      })
    },
  },
}
</script>
